/* ==========================================================================
   MSG-01 · Messages.module.css
   Cabecera, barra de acciones, aviso de error, estado de carga y paginación.
   ========================================================================== */

.screen {
  min-width: 0;
}

/* --- Cabecera de pantalla ---------------------------------------------- */

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--bw-steel-mist);
}

.pageTitle {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.pageSub {
  max-width: 560px;
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* --- Estado E2EE -------------------------------------------------------- */

.e2eeBar {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin-bottom: 14px;
  padding: 6px 10px;
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  background: var(--bw-badge-success-bg);
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  font-weight: 500;
  letter-spacing: var(--bw-ls-hint);
  text-transform: uppercase;
  color: var(--bw-success-dark);
}

.e2eeIcon {
  font-size: 12px;
  color: var(--bw-signal-green);
}

/* --- Barra de acciones -------------------------------------------------- */

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchForm {
  position: relative;
  flex: 1 1 300px;
  max-width: 300px;
  margin: 0;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 15px;
  color: var(--bw-input-placeholder);
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s ease;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.contactWrap {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.newContactBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: 0;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  white-space: nowrap;
}

.newContactBtn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.scopeNote {
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
}

.pagInfo {
  margin-left: auto;
  font-family: var(--bw-font-mono);
  font-size: 11px;
  white-space: nowrap;
  color: var(--bw-input-placeholder);
}

/* --- Aviso de error y carga --------------------------------------------- */

.errorBanner {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-bottom: 14px;
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 6px;
  background: var(--bw-sensitive-bg);
  font-size: 13px;
  line-height: 1.5;
  color: var(--bw-error-text);
}

.errorBanner i {
  flex-shrink: 0;
  margin-top: 2px;
}

.loadingState {
  padding: 40px 20px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-warm-cream);
  text-align: center;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

/* --- Paginación ---------------------------------------------------------- */

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition:
    border-color 0.12s ease,
    color 0.12s ease;
}

.pageBtn:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  cursor: default;
}

.pageActive,
.pageActive:hover:not(:disabled) {
  border-color: var(--bw-deep-steel);
  background: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

.pageArrow {
  color: var(--bw-ink-steel);
}

.pageArrow:disabled {
  color: var(--bw-hint-steel);
}

