import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';

import type { MemberProfile } from '../../lib/session';
import {
  fetchThreadPage,
  pageCount,
  sanitizeSearch,
  type ThreadPage,
} from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * Cableado por App.tsx después de escribirse esta pantalla (F-118).
   * Se declara aquí porque es la firma pública del componente, pero MSG-02
   * no está en el alcance del MVP: se recibe y no se usa.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Convierte un rechazo de PostgREST en texto para el aviso (F-128).
 *
 * Lo que captura el `catch` no siempre es un `Error`: PostgREST rechaza con
 * un objeto plano `{ code, message }`, así que `String(e)` daría
 * `[object Object]`. Hay que leer `code` y `message` cuando existan y
 * pintarlos junto a la frase para humanos.
 */
function describeError(caught: unknown): string {
  if (caught && typeof caught === 'object') {
    const obj = caught as Record<string, unknown>;
    const parts = ['code', 'message']
      .map((key) => (typeof obj[key] === 'string' ? (obj[key] as string) : ''))
      .filter((part) => part.length > 0);
    if (parts.length > 0) return parts.join(' · ');
  }
  if (caught instanceof Error) return caught.message;
  return 'Error desconocido';
}

/**
 * MSG-01 · Lista de Hilos.
 *
 * Pantalla de contenido del módulo de mensajería: es la dueña del estado de
 * búsqueda y de página, y consulta `fetchThreadPage` con la organización del
 * perfil.
 */
export function Messages({ profile, now }: MessagesProps) {
  const [searchInput, setSearchInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(1);
  const [threadPage, setThreadPage] = useState<ThreadPage | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);
    setLoadError(null);
    setThreadPage(null);

    fetchThreadPage({ orgId: profile.orgId, search: searchTerm, page })
      .then((result) => {
        if (cancelled) return;
        setThreadPage(result);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setLoadError(describeError(err));
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, searchTerm, page]);

  const handleSearchSubmit = (event: FormEvent) => {
    event.preventDefault();
    setPage(1);
    setSearchTerm(sanitizeSearch(searchInput));
  };

  const total = threadPage?.total ?? 0;
  const pages = pageCount(total);
  const currentNow = now ?? new Date();

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      {/* Estado E2EE. En el MVP las claves viven en memoria de sesión y no hay
          passphrase ni recuperación: el aviso con «Introducir frase de
          seguridad» no se pinta como acción disponible. */}
      <span className={styles.e2eeBar}>
        <i className={`ti ti-lock ${styles.e2eeIcon}`} aria-hidden="true" />
        E2EE activo · claves en memoria de sesión
      </span>

      <div className={styles.actionsBar}>
        <form className={styles.searchForm} role="search" onSubmit={handleSearchSubmit}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="search"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar hilos por nombre de organización"
            value={searchInput}
            onChange={(event) => setSearchInput(event.target.value)}
            autoComplete="off"
          />
        </form>

        <div className={styles.contactWrap}>
          <button type="button" className={styles.newContactBtn} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.scopeNote} data-testid="directorio-scope">
            El Directorio (DIR-01) queda fuera del MVP.
          </span>
        </div>

        <span className={styles.pagInfo} data-testid="pag-info">
          {total.toLocaleString('es-ES')} hilos · Página {page} de {pages}
        </span>
      </div>

      {loadError ? (
        <div className={styles.errorBanner} role="alert">
          <i className="ti ti-alert-triangle" aria-hidden="true" />
          <span>No se pudieron cargar los hilos. {loadError}</span>
        </div>
      ) : threadPage ? (
        // `onOpenThread` se ignora (F-118): abrir un hilo no lleva a MSG-02.
        <ThreadList threads={threadPage.threads} now={currentNow} onOpen={() => undefined} />
      ) : isLoading ? (
        <div className={styles.loadingState} aria-live="polite">
          Cargando hilos…
        </div>
      ) : (
        <ThreadList threads={[]} now={currentNow} onOpen={() => undefined} />
      )}

      {threadPage && pages > 1 && (
        <div className={styles.pagination}>
          <button
            type="button"
            className={`${styles.pageBtn} ${styles.pageArrow}`}
            onClick={() => setPage((current) => Math.max(1, current - 1))}
            disabled={page === 1}
            aria-label="Página anterior"
          >
            ‹
          </button>

          {Array.from({ length: pages }, (_, index) => index + 1).map((pageNumber) => (
            <button
              key={pageNumber}
              type="button"
              className={
                pageNumber === page
                  ? `${styles.pageBtn} ${styles.pageActive}`
                  : styles.pageBtn
              }
              disabled={pageNumber === page}
              onClick={() => setPage(pageNumber)}
            >
              {pageNumber}
            </button>
          ))}

          <button
            type="button"
            className={`${styles.pageBtn} ${styles.pageArrow}`}
            onClick={() => setPage((current) => Math.min(pages, current + 1))}
            disabled={page === pages}
            aria-label="Página siguiente"
          >
            ›
          </button>
        </div>
      )}
    </div>
  );
}

