/* ==========================================================================
   MSG-01 · ThreadList.module.css
   Tarjeta de hilos y estado vacío.
   ========================================================================== */

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row + .row {
  border-top: 1px solid var(--bw-divider-mist);
}

.rowButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0 12px;
  align-items: start;
  width: 100%;
  padding: 14px 18px;
  border: 0;
  background: transparent;
  color: var(--bw-deep-steel);
  font-family: var(--bw-font-body);
  text-align: left;
  cursor: pointer;
  transition: background-color 0.1s ease;
}

.rowButton:hover {
  background: var(--bw-hover-surface);
}

.rowButton:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.mainCol {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.orgLine {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  flex-shrink: 0;
  padding: 1px 6px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 2px;
  background: var(--bw-cold-white);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  white-space: nowrap;
  color: var(--bw-steel-mist);
}

.previewLine {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
}

.preview {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.timestamp {
  justify-self: end;
  padding-top: 1px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  white-space: nowrap;
  color: var(--bw-input-placeholder);
}

.stateBadge {
  display: inline-block;
  flex-shrink: 0;
  padding: 2px 7px;
  border: 1px solid transparent;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  white-space: nowrap;
}

.badgeNeutral {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border);
  color: var(--bw-steel-mist);
}

.badgeInfo {
  background: var(--bw-chip-active-bg);
  border-color: var(--bw-chip-active-border);
  color: var(--bw-calibration-blue);
}

.badgeWarn {
  background: var(--bw-badge-warning-bg);
  border-color: var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

.badgeSuccess {
  background: var(--bw-badge-success-bg);
  border-color: var(--bw-badge-success-border);
  color: var(--bw-signal-green);
}

.badgeClosed {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border);
  color: var(--bw-input-placeholder);
  text-decoration: line-through;
}

/* --------------------------------------------------------------------------
   Estado vacío (F-128, F-141)
   Va en un contenedor propio, fuera de cualquier <ul>: con cero hilos el
   documento no puede contener ni un solo `listitem`.
   -------------------------------------------------------------------------- */

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 48px 24px;
  border: 1px dashed var(--bw-brass-border-strong);
  border-radius: 8px;
  background: var(--bw-warm-cream);
  text-align: center;
}

.emptyText {
  max-width: 420px;
  margin: 0 0 8px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-deep-steel);
}

.emptyBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 36px;
  margin-top: 6px;
  padding: 0 18px;
  border: 0;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
}

.emptyBtn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.emptyNote {
  margin: 6px 0 0;
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
}

