import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

/**
 * El diccionario tono→clase se declara como `string | undefined` a propósito
 * (F-143): con `noUncheckedIndexedAccess`, una clase que falte en el módulo
 * CSS no puede llenar el hueco con la palabra `undefined`. El `??` está en el
 * único sitio donde se consume, la fila.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.badgeNeutral,
  info: styles.badgeInfo,
  warn: styles.badgeWarn,
  success: styles.badgeSuccess,
  closed: styles.badgeClosed,
};

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Pinta las filas en el orden en que las recibe — el orden lo decide el
 * servidor. Cada hilo vive en un `<li>` que conserva su rol implícito
 * `listitem` (F-131); lo pulsable es el `<button>` de dentro.
 */
export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras
          organizaciones.
        </p>
        <button type="button" className={styles.emptyBtn} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyNote}>El Directorio queda fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          <li key={thread.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowButton}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.mainCol}>
                <span className={styles.orgLine}>
                  <span className={styles.orgName}>{thread.counterpartyName}</span>
                  <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                </span>
                <span className={styles.previewLine}>
                  <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
                  <span className={`${styles.stateBadge} ${toneClass}`}>{thread.state}</span>
                </span>
              </span>
              <time className={styles.timestamp} dateTime={thread.lastItemAt}>
                {relativeTime(thread.lastItemAt, now)}
              </time>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
